import numpy as np, time
from collections import OrderedDict

class PyLRU:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = OrderedDict()
    def get(self,key):
        if key not in self.cache:
            return -1
        self.order.move_to_end(key)
        return self.cache[key]
    def put(self,key,val):
        if key in self.cache:
            self.cache[key]=val
            self.order.move_to_end(key)
        else:
            if len(self.cache)>=self.capacity:
                old_key,_=self.order.popitem(last=False)
                del self.cache[old_key]
            self.cache[key]=val
            self.order[key]=None

    def run_ops(self,ops):
        # collect get results into list then array
        out=[]
        for row in ops:
            is_put, key, val = row
            if is_put:
                self.put(int(key), int(val))
            else:
                out.append(self.get(int(key)))
        return np.array(out, dtype=np.int64)

def gen_ops(n, capacity, seed):
    rng = np.random.default_rng(seed)
    is_put = rng.random(n) < 0.5
    ops = np.empty((n,3), dtype=np.int64)
    ops[:,0] = is_put
    ops[:,1] = rng.integers(0, capacity*3, n, endpoint=True)
    ops[:,2] = np.where(is_put, rng.integers(0, 100_000, n, endpoint=True), 0)
    return ops

n=2_000_000
capacity=10_000
seed=99
ops=gen_ops(n, capacity, seed)
cache=PyLRU(capacity)
start=time.perf_counter()
cache.run_ops(ops)
print('PyLRU time', time.perf_counter()-start)
